<script setup lang="ts">
import {computed} from 'vue'
const props=defineProps<{data:any;homework:any[]}>()
const emit=defineEmits<{students:[id:number];quick:[mode:string,id:number];register:[id:number];attendance:[];track:[homework:any]}>()
const weekday=computed(()=>new Date(props.data.today+'T00:00:00Z').getUTCDay()||7)
const lessons=computed(()=>props.data.lessons.filter((l:any)=>l.day_of_week===weekday.value).sort((a:any,b:any)=>a.start_time.localeCompare(b.start_time)))
const due=computed(()=>props.homework.filter(h=>h.is_active&&h.due_on===props.data.today))
const upcoming=computed(()=>props.homework.filter(h=>h.is_active&&h.due_on>props.data.today).sort((a,b)=>a.due_on.localeCompare(b.due_on)).slice(0,5))
const classes=computed<any[]>(()=>[...new Map<number,any>([...props.data.assignments,...props.data.homerooms].map((c:any)=>[c.class_id,c])).values()])
const label=(c:any)=>'Grade '+c.grade_label+' · Class '+c.class_name
const lessonClasses=(l:any)=>props.data.assignments.filter((a:any)=>a.offering_id===l.course_offering_id)
</script>
<template><section class="today"><div class="today-heading"><div><p class="date">{{data.today}} · Nepal school date</p><h2>Your teaching day</h2><p>Start with your next classroom task.</p></div><button v-if="data.homerooms.length" type="button" @click="emit('attendance')">Take homeroom attendance</button></div><div class="metrics"><div><strong>{{lessons.length}}</strong><span>Lessons today</span></div><div><strong>{{due.length}}</strong><span>Assignments due today</span></div><div><strong>{{classes.length}}</strong><span>Assigned classes</span></div></div><div class="today-grid"><section class="card"><h3>Today’s lessons</h3><p v-if="!lessons.length" class="empty">No lessons scheduled today.</p><article v-for="l in lessons" :key="l.id" class="lesson-row"><time>{{l.start_time}}–{{l.end_time}}</time><div><strong>{{lessonClasses(l)[0]?.course_name||'Lesson'}}</strong><small>{{l.location||'Room not set'}}</small><div v-for="c in lessonClasses(l)" :key="c.class_id" class="class-actions"><button class="text-action" type="button" @click="emit('students',c.class_id)">{{label(c)}}</button><button type="button" class="secondary" @click="emit('quick','homework',c.class_id)">Homework</button><button type="button" class="secondary" @click="emit('quick','notice',c.class_id)">Notice</button></div></div></article></section><section class="card"><h3>Due today</h3><p v-if="!due.length" class="empty">No assignments due today.</p><article v-for="h in due" :key="h.id" class="due-row"><div><strong>{{h.title}}</strong><small>{{classes.find(c=>c.class_id===h.class_id)?label(classes.find(c=>c.class_id===h.class_id)):''}}</small></div><button type="button" @click="emit('track',h)">Mark homework</button></article><h3 class="next-heading">Coming up</h3><p v-if="!upcoming.length" class="empty">No upcoming homework in the recent assignment list.</p><article v-for="h in upcoming" :key="h.id" class="upcoming"><span>{{h.title}}</span><time>{{h.due_on}}</time></article><p class="footnote">Homework overview uses your latest 100 assignments. Due dates do not indicate missing student work.</p></section></div><section class="card"><h3>My classes</h3><p v-if="!classes.length" class="empty">No classes assigned. Ask your administrator to link your teaching subjects.</p><div class="class-grid"><article v-for="c in classes" :key="c.class_id" class="class-card"><strong>{{label(c)}}</strong><small>{{data.homerooms.some((h:any)=>h.class_id===c.class_id)?'Your homeroom':'Subject class'}}</small><div class="class-actions"><button type="button" class="secondary" @click="emit('students',c.class_id)">Students</button><button type="button" class="secondary" @click="emit('register',c.class_id)">Homework register</button><button v-if="data.assignments.some((a:any)=>a.class_id===c.class_id)" type="button" @click="emit('quick','homework',c.class_id)">Assign homework</button><button type="button" class="secondary" @click="emit('quick','notice',c.class_id)">Post notice</button></div></article></div></section></section></template>
<style scoped>
