ackground:var(--ui-legacy-f6f9f7);border:1px solid var(--ui-legacy-dce6df);border-radius:8px}.today button:focus-visible{outline:3px solid var(--ui-legacy-4a8660);outline-offset:2px}@media(max-width:800px){.today-grid{grid-template-columns:minmax(0,1fr)}}@media(max-width:550px){.metrics{gap:7px}.metrics>div{padding:10px}.metrics strong{font-size:22px}.class-grid{grid-template-columns:minmax(0,1fr)}.lesson-row{grid-template-columns:minmax(0,1fr)}.due-row{align-items:start;flex-wrap:wrap}.card{padding:14px}.today h2{font-size:21px}}
